            \bigwedge d^2.
        \end{align*}

Note that trivially $c_0\mathbb{I} \in \mathcal{U}_q$. Consider an arbitrary point $\Sigma^0 \in \mathcal{U}_q(s_0(n))$ and 
\begin{align*}
    \Sigma^{1} &= \alpha \Sigma^0 + (1-\alpha)c_0\mathbb{I}.
\end{align*}
First note that 
\begin{align*}
    \lambda_{\min}(\Sigma^1) &= \lambda_{\min}(\alpha \Sigma^0 + (1-\alpha)c_0\mathbb{I}) 
    \\ &= \alpha \lambda_{\min}(\Sigma^0) + (1-\alpha)c_0
    \\ &\geq c_0
\end{align*}
and
\begin{align*}
    \lambda_{\max}(\Sigma^1) &= \lambda_{\max}(\alpha \Sigma^0 + (1-\alpha)c_0\mathbb{I}) 
    \\ &= \alpha \lambda_{\max}(\Sigma^0) + (1-\alpha)c_0
    \\ &\leq c_1.
\end{align*}
We conclude by showing separately that the column bounds hold when $q \in (0,1)$ and $q=0$.
\\\textbf{Case 1: $q > 0$.}
For an arbitrary $i \in n$ we have 
\begin{align*}
    \sum_{j=1}^n |\sigma^1_{ij}|^q &= \sum_{j=1}^n |\alpha \sigma_{ij}^0 + (1-\alpha) c_01\kern-4pt 1(i=j)|^q
    \\ &= |\alpha\sigma_{ii}^0 + (1-\alpha)c_0|^q + \sum_{j\neq i}\alpha^q|\sigma_{ij}^0|^q
    \\ &\leq |\alpha\sigma_{ii}^0 + (1-\alpha)\sigma_{ii}^0|^q + \sum_{j\neq i}\alpha^q|\sigma_{ij}^0|^q
    \\ &\leq \sum_{j=1}^n |\sigma^0_{ij}|^q \leq s_0(n),
\end{align*}
so the column bounds hold.
\\\textbf{Case 2: $q =0$} Note that in this case shrinking $\Sigma^0$ and adding to the diagonal does not incease the support, because $\lambda_{\min}(\Sigma^0) \geq c_0 > 0$ the diagonal of $\Sigma^0$ must be positive.

Plug in our value of $\delta$ to \eqref{eq:n_to_log_n}see that
    \begin{align*}
    \log \bigg( n^{2-\frac{2}{2-q}}s_0(n)^{-\frac{2}{2-q}}\delta^{\frac{2q}{2-q}} \bigg) &\lesssim \log\bigg(n^{2-\frac{2}{2-q}}s_0(n)^{-\frac{2}{2-q}}\bigg(ns_0(n)\left(\frac{\log(n)}{N}\right)^{\frac{2-q}{2}}\bigg)^{\frac{q}{2-q}} \bigg)
    \\&= \log\bigg(n^{2-\frac{2}{2-q}+\frac{q}{2-q}}s_0(n)^{\frac{q-2}{2-q}}\bigg(\frac{\log n}{N}\bigg)^{q/2}\bigg)
    \\&= \log\bigg(\frac{n}{s_0(n)}\bigg(\frac{\log n}{N}\bigg)^{q/2}\bigg)
    \\ &= \log n - \log s_0(n) + \frac{q}{2}\log\bigg(\frac{\log n}{N}\bigg)
    \\ &\lesssim \log n + \frac{q}{2}\log\bigg(\frac{\log n}{N}\bigg)
\end{align*}
which is bounded above by a constant multiple of $\log (n)$ if $\frac{\log n}{N} \lesssim  n$ (which is weaker than our required $N \gtrsim n^2$), and gives \eqref{eq:n_to_log_n}. 
Next, plug in the value of $\delta$ to \eqref{eq:Rdelta_bound} get that
\begin{align*}
