    \\ n^{1/2 - 1/q} &\lesssim s_0(n)^{1/2-1/q} \bigg(\frac{\log n}{N}\bigg)^{1/2-q/4}
\end{align*}
and we have that 
\begin{align*}
\bigg(\frac{n}{s_0(n)}\bigg)^{1/2-1/q} &\lesssim \bigg(\frac{\log n}{N}\bigg)^{1/2-q/4}
\\ \bigg(\frac{s_0(n)}{n}\bigg)^{(2-q)/(2q)} &\lesssim \bigg(\frac{\log n}{N}\bigg)^{(2-q)/4}
\\ \frac{s_0(n)}{n} &\lesssim \bigg(\frac{\log n}{N}\bigg)^{q/2}
\\ s_0(n) & \lesssim n\bigg(\frac{\log n}{N}\bigg)^{q/2}
\end{align*}
and note that this is a weaker condition than $s_0(n) \lesssim nN^{-q/2}\log^{q/2-1}n$.
